// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
outer_d     = 80;    // outer rim diameter
rim_w       = 5;     // rim width
hub_d       = 16;    // hub diameter
axle_d      = 5;     // axle hole diameter
spoke_w     = 5;     // spoke width
spoke_count = 8;     // number of spokes
thickness   = 5;     // part thickness
eps         = 0.5;   // cutter overshoot

$fn = 96;

// ---- Model ----
difference() {
    union() {
        // Rim
        cylinder(d = outer_d, h = thickness);
        // Hub
        translate([0, 0, -eps])
            cylinder(d = hub_d, h = thickness + 2 * eps);
        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_d / 2 - 1, -spoke_w / 2, 0])
                    cube([outer_d / 2 - hub_d / 2 + 2, spoke_w, thickness]);
    }
    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
