// Spoked wheel for small sample cart
// Flat part, printed lying flat on the bed

// ---- Dimensions (mm) ----
outer_d     = 80;    // outer rim diameter
rim_w       = 5;     // rim width
hub_d       = 16;    // hub diameter
axle_d      = 5;     // axle hole diameter
spoke_w     = 5;     // spoke width
spoke_count = 8;     // number of spokes
thickness   = 5;     // part thickness

$fn = 96;            // resolution for curved shapes

// ---- Derived ----
inner_d = outer_d - 2 * rim_w;   // ring inner diameter (70)
spoke_len = (outer_d - hub_d) / 2; // spoke length from hub to rim (32)

// ---- Model ----
difference() {
    union() {
        // Outer rim (ring)
        difference() {
            cylinder(d = outer_d, h = thickness);
            translate([0, 0, -1])
                cylinder(d = inner_d, h = thickness + 2);
        }

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes, first along +X
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([0, -spoke_w / 2, 0])
                    cube([spoke_len + hub_d / 2, spoke_w, thickness]);
    }

    // Axle hole through hub centre
    translate([0, 0, -1])
        cylinder(d = axle_d, h = thickness + 2);
}
