// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to part_t

$fn = 128;

// --- Dimensions (mm) ---
part_t      = 6;    // wheel thickness
rim_d       = 80;   // outer rim diameter
rim_w       = 4;    // rim width
hub_d       = 16;   // hub diameter
axle_d      = 8;    // axle hole diameter
spoke_w     = 5;    // spoke width
spoke_count = 4;    // number of spokes, evenly spaced
start_angle = 0;    // first spoke along +X axis

// --- Derived ---
rim_id = rim_d - 2 * rim_w;  // inner diameter of rim

difference() {
    union() {
        // Outer rim
        cylinder(d = rim_d, h = part_t);
        // Hub (overlaps rim slightly for a clean union)
        translate([0, 0, -0.01])
            cylinder(d = hub_d, h = part_t + 0.02);
        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, start_angle + i * 360 / spoke_count])
                translate([0, -spoke_w / 2, 0])
                    cube([rim_id / 2 + rim_w, spoke_w, part_t]);
    }
    // Axle hole through centre
    translate([0, 0, -1])
        cylinder(d = axle_d, h = part_t + 2);
}
