// Tapered riser block for a beaker
// Print orientation: wide base on the bed (z = 0), narrow top at z = block_h

// ---------- Dimensions (mm) ----------
base_w      = 100;   // base side length (X and Y)
base_h      = 0;     // base thickness (flat plate, z = 0)
block_h     = 30;    // riser height (top face at z = 30)
top_w       = 80;    // top face side length (X and Y)
pocket_w    = 72;    // square pocket side length (X and Y)
pocket_d    = 8;     // square pocket depth from top face
eps         = 0.5;   // overshoot for clean boolean cuts

$fn = 64;

// ---------- Model ----------
difference() {
    union() {
        // Base plate at z = 0
        translate([-base_w/2, -base_w/2, base_h])
            cube([base_w, base_w, base_h + 0.01]);

        // Tapered riser: hull between base outline and top outline
        hull() {
            translate([-base_w/2, -base_w/2, base_h])
                cube([base_w, base_w, 0.01]);
            translate([-top_w/2, -top_w/2, block_h])
                cube([top_w, top_w, 0.01]);
        }
    }

    // Square pocket cut into the top face
    translate([-pocket_w/2, -pocket_w/2, block_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
